{
  "themes": [
    {
      "cluster": 24,
      "name": "Rider Rating for Uber Pool",
      "description": "Customers want the ability to rate and review fellow riders in shared pool trips."
    },
    {
      "cluster": 25,
      "name": "Driver Cancellations and No‑Shows",
      "description": "Users report drivers refusing trips or canceling after booking, leaving them unable to get a ride."
    },
    {
      "cluster": 26,
      "name": "Unexpected or Fraudulent Card Charges",
      "description": "Riders see duplicate, unauthorized or unexplained charges on their payment cards."
    },
    {
      "cluster": 27,
      "name": "Missing or Inaccessible Invoices/Receipts",
      "description": "Customers cannot locate, download, or receive trip receipts and business invoices."
    },
    {
      "cluster": 28,
      "name": "Refunds for Driver‑Cancelled Trips",
      "description": "When a driver cancels a ride, users want the charge removed or refunded to their card."
    },
    {
      "cluster": 29,
      "name": "Toll and Fare Transparency Issues",
      "description": "Riders dispute extra toll fees or fare amounts that differ from the quoted price."
    },
    {
      "cluster": 30,
      "name": "Duplicate Ride Charges",
      "description": "Customers are billed multiple times for the same trip or see unexpected surcharges."
    },
    {
      "cluster": 31,
      "name": "Charges for Trips Not Taken",
      "description": "Users are charged for trips they never rode or that were cancelled without their consent."
    },
    {
      "cluster": 32,
      "name": "Cancellation Fees When Driver Cancels",
      "description": "Riders are charged cancellation fees even though the driver was the one who cancelled."
    },
    {
      "cluster": 33,
      "name": "Driver‑Initiated Mid‑Trip Cancellations",
      "description": "Drivers abandon trips or force riders to cancel midway, often citing distance or surge."
    },
    {
      "cluster": 34,
      "name": "Reporting Problematic Drivers",
      "description": "Customers seek ways to report drivers for unsafe behavior, misuse of contact info, or poor service."
    },
    {
      "cluster": 35,
      "name": "Driver Document Verification Failures",
      "description": "Prospective drivers struggle to upload or get approval for licenses, registration, and insurance."
    }
  ]
}
